import json
d=json.load(open('products/research/tender-continuity/raw-page1.json'))
rs=d.get('releases',[])
print('releases',len(rs),'next',d.get('links',{}).get('next'))
for r in rs:
  t=r.get('tender',{});tp=t.get('tenderPeriod',{}) or {}
  cl=t.get('classification',{}) or {}
  cpvs=[cl.get('id','')]+[c.get('classification',{}).get('id','') for it in t.get('items',[]) for c in [it] if c.get('classification')]+[a.get('id','') for it in t.get('items',[]) for a in it.get('additionalClassifications',[])]
  print(r.get('id'),r.get('tag'),t.get('status'),tp.get('endDate'),'|',(t.get('title') or '')[:90],'|',','.join(sorted(set(x for x in cpvs if x)))[:80])
